@@ -0,0 +1,54 @@
+package models
+
+import "time"
+
+// KEVType identifies the source of a Known Exploited Vulnerability entry.
+type KEVType string
+
+const (
+	// CISAKEVType identifies entries from CISA's KEV catalog.
+	CISAKEVType KEVType = "cisa"
+	// VulnCheckKEVType identifies entries from VulnCheck's KEV catalog.
+	VulnCheckKEVType KEVType = "vulncheck"
+)
+
+// KEV contains common information about a Known Exploited Vulnerability.
+type KEV struct {
+	Type                       KEVType       `json:"type"`
+	VendorProject              string        `json:"vendorProject,omitempty"`
+	Product                    string        `json:"product,omitempty"`
+	VulnerabilityName          string        `json:"vulnerabilityName,omitempty"`
+	ShortDescription           string        `json:"shortDescription,omitempty"`
+	RequiredAction             string        `json:"requiredAction,omitempty"`
+	KnownRansomwareCampaignUse string        `json:"knownRansomwareCampaignUse,omitempty"`
+	DateAdded                  time.Time     `json:"dateAdded,omitempty"`
+	DueDate                    *time.Time    `json:"dueDate,omitempty"`
+	CISA                       *CISAKEV      `json:"cisa,omitempty"`
+	VulnCheck                  *VulnCheckKEV `json:"vulncheck,omitempty"`
+}
+
+// CISAKEV contains CISA-specific information for a KEV entry.
+type CISAKEV struct {
+	Note string `json:"note,omitempty"`
+}
+
+// VulnCheckKEV contains VulnCheck-specific information for a KEV entry.
+type VulnCheckKEV struct {
+	XDB                  []VulnCheckXDB                  `json:"xdb,omitempty"`
+	ReportedExploitation []VulnCheckReportedExploitation `json:"reportedExploitation,omitempty"`
+}
+
+// VulnCheckXDB contains exploit information from VulnCheck's XDB.
+type VulnCheckXDB struct {
+	XDBID       string    `json:"xdbID,omitempty"`
+	XDBURL      string    `json:"xdbURL,omitempty"`
+	DateAdded   time.Time `json:"dateAdded,omitempty"`
+	ExploitType string    `json:"exploitType,omitempty"`
+	CloneSSHURL string    `json:"cloneSSHURL,omitempty"`
+}
+
+// VulnCheckReportedExploitation contains a reported exploitation record.
+type VulnCheckReportedExploitation struct {
+	URL       string    `json:"url,omitempty"`
+	DateAdded time.Time `json:"dateAdded,omitempty"`
+}
